function loadBlogData() {
	function fetchPage(pageNum) {
		return fetch('/wp-json/wp/v2/posts?per_page=100&page=' + pageNum + '&_embed&orderby=date&order=desc')
			.then(function (res) { return res.ok ? res.json() : []; })
			.catch(function () { return []; });
	}
	return fetchPage(1).then(function (page1) {
		if (page1.length < 100) return page1;
		return fetchPage(2).then(function (page2) {
			if (page2.length < 100) return page1.concat(page2);
			return fetchPage(3).then(function (page3) { return page1.concat(page2, page3); });
		});
	}).then(function (posts) {
		if (!posts || !posts.length) return BLOG_DATA;
		return posts
			.map(function (p) {
					const media = p._embedded && p._embedded['wp:featuredmedia'] && p._embedded['wp:featuredmedia'][0];
					const terms = p._embedded && p._embedded['wp:term'] ? [].concat.apply([], p._embedded['wp:term']) : [];
					const catTerm = terms.find(function (t) { return t.taxonomy === 'category' && t.name !== 'Uncategorized'; });
					const tagTerms = terms.filter(function (t) { return t.taxonomy === 'post_tag'; }).map(function (t) { return t.name; });
					const authorName = p._embedded && p._embedded.author && p._embedded.author[0] ? p._embedded.author[0].name : 'RealDeal Editorial Team';
					const excerptText = (p.excerpt && p.excerpt.rendered ? p.excerpt.rendered : '').replace(/<[^>]+>/g, '').trim();
					return {
						slug: p.slug,
						title: (p.title && p.title.rendered) || p.slug,
						excerpt: excerptText || (p.title && p.title.rendered) || '',
						image: media ? media.source_url : '../images/index-image.jpg',
						category: catTerm ? catTerm.name : 'Blog',
						tags: tagTerms.length ? tagTerms : ['Blog'],
						author: authorName,
						date: (p.date || '').slice(0, 10),
						readingTime: Math.max(3, Math.round((p.content && p.content.rendered ? p.content.rendered.replace(/<[^>]+>/g, '').split(/\s+/).length : 600) / 200)),
						popular: false,
						featured: false,
						detailUrl: p.link
					};
				});
		})
		.catch(function () { return BLOG_DATA; });
}

const CATEGORY_ACCENTS = { "Accounting and Bookkeeping":"var(--rd-teal)", "Web Design & Development":"var(--rd-orange)", "Digital Marketing":"var(--rd-blue)", "SEO":"var(--rd-green)" };

(function () {
	"use strict";
	const grid = document.getElementById("blogGrid");
	const statusEl = document.getElementById("blogStatus");
	const searchInput = document.getElementById("blogSearch");
	const catSel = document.getElementById("filterCategory");
	const tagSel = document.getElementById("filterTag");
	const authorSel = document.getElementById("filterAuthor");
	const yearSel = document.getElementById("filterYear");
	const popularChk = document.getElementById("filterPopular");
	const featuredChk = document.getElementById("filterFeatured");
	const sortSel = document.getElementById("sortBy");
	const resetBtn = document.getElementById("filtersReset");
	const loadMoreBtn = document.getElementById("loadMoreBtn");

	const PAGE_SIZE = 6;
	let visibleCount = PAGE_SIZE;
	let allItems = [];

	function uniqueSorted(items, key) {
		return Array.from(new Set(items.map((i) => i[key]).filter(Boolean))).sort();
	}

	function populateSelect(select, values) {
		values.forEach((v) => {
			const opt = document.createElement("option");
			opt.value = v;
			opt.textContent = v;
			select.appendChild(opt);
		});
	}

	function formatDate(d) {
		return new Date(d).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
	}

	function cardTemplate(item) {
		const tags = item.tags.map((t) => `<span>${t}</span>`).join("");
		return `
		<article class="result-card" style="--card-accent:${CATEGORY_ACCENTS[item.category] || "var(--rd-orange)"}">
			<a class="card-link" href="${item.detailUrl}" aria-label="Read ${item.title}"></a>
			<div class="card-media">
				<img src="${item.image}" alt="${item.title}" loading="lazy" width="800" height="500">
				<span class="card-badge">${item.category}</span>
				${item.featured ? '<span class="card-featured" title="Featured post"><i class="fa-solid fa-star"></i></span>' : ""}
			</div>
			<div class="card-body">
				<div class="card-meta"><span>${formatDate(item.date)}</span><span>&middot;</span><span>${item.readingTime} min read</span><span>&middot;</span><span>${item.author}</span>${item.popular ? '<span>&middot;</span><span><i class="fa-solid fa-fire"></i> Popular</span>' : ""}</div>
				<h3>${item.title}</h3>
				<p>${item.excerpt}</p>
				<div class="card-tags">${tags}</div>
				<div class="card-actions">
					<a class="btn btn-dark" href="${item.detailUrl}">Read More <i class="fa-solid fa-arrow-right"></i></a>
				</div>
			</div>
		</article>`;
	}

	function getFiltered() {
		const q = searchInput.value.trim().toLowerCase();
		return allItems.filter((item) => {
			if (catSel.value && item.category !== catSel.value) return false;
			if (tagSel.value && !item.tags.includes(tagSel.value)) return false;
			if (authorSel.value && item.author !== authorSel.value) return false;
			if (yearSel.value && String(new Date(item.date).getFullYear()) !== yearSel.value) return false;
			if (popularChk.checked && !item.popular) return false;
			if (featuredChk.checked && !item.featured) return false;
			if (q) {
				const hay = (item.title + " " + item.excerpt + " " + item.tags.join(" ")).toLowerCase();
				if (!hay.includes(q)) return false;
			}
			return true;
		});
	}

	function getSorted(items) {
		const sorted = items.slice();
		switch (sortSel.value) {
			case "oldest": sorted.sort((a, b) => new Date(a.date) - new Date(b.date)); break;
			case "popular": sorted.sort((a, b) => (b.popular === a.popular) ? 0 : (b.popular ? 1 : -1)); break;
			case "featured": sorted.sort((a, b) => (b.featured === a.featured) ? 0 : (b.featured ? 1 : -1)); break;
			case "az": sorted.sort((a, b) => a.title.localeCompare(b.title)); break;
			default: sorted.sort((a, b) => new Date(b.date) - new Date(a.date));
		}
		return sorted;
	}

	function render() {
		const filtered = getSorted(getFiltered());
		const slice = filtered.slice(0, visibleCount);
		grid.innerHTML = slice.length
			? slice.map(cardTemplate).join("")
			: '<div class="no-results"><i class="fa-solid fa-newspaper"></i>No articles match these filters.</div>';
		statusEl.textContent = filtered.length ? `Showing ${slice.length} of ${filtered.length} articles` : "";
		loadMoreBtn.style.display = visibleCount < filtered.length ? "inline-flex" : "none";
	}

	function resetPaging() { visibleCount = PAGE_SIZE; render(); }

	[catSel, tagSel, authorSel, yearSel, sortSel].forEach((el) => el.addEventListener("change", resetPaging));
	popularChk.addEventListener("change", resetPaging);
	featuredChk.addEventListener("change", resetPaging);
	searchInput.addEventListener("input", resetPaging);
	loadMoreBtn.addEventListener("click", () => { visibleCount += PAGE_SIZE; render(); });
	resetBtn.addEventListener("click", () => {
		[catSel, tagSel, authorSel, yearSel].forEach((el) => el.value = "");
		popularChk.checked = false;
		featuredChk.checked = false;
		searchInput.value = "";
		sortSel.value = "latest";
		resetPaging();
	});

	loadBlogData().then((items) => {
		allItems = items;
		populateSelect(catSel, uniqueSorted(items, "category"));
		populateSelect(tagSel, Array.from(new Set(items.flatMap((i) => i.tags))).sort());
		populateSelect(authorSel, uniqueSorted(items, "author"));
		populateSelect(yearSel, Array.from(new Set(items.map((i) => new Date(i.date).getFullYear()))).sort((a, b) => b - a).map(String));

		const schema = {
			"@context": "https://schema.org",
			"@type": "Blog",
			"name": "RealDeal IT Center Blog",
			"blogPost": items.map((item) => ({
				"@type": "BlogPosting",
				"headline": item.title,
				"description": item.excerpt,
				"image": item.image,
				"datePublished": item.date,
				"author": { "@type": "Organization", "name": item.author },
				"url": "https://jahangirhussen.github.io/RealDeal_Home/blogs/" + item.detailUrl
			}))
		};
		document.getElementById("blog-schema").textContent = JSON.stringify(schema);

		render();
	});
})();
</script>
<script src="../assets/site-nav.js?v=3" defer></script>
</body>
</html>
